params.command:
$ErrorActionPreference='Stop'
$repo = Join-Path $env:USERPROFILE 'HeavenBridgeRepo'
$tmp = Join-Path $env:USERPROFILE 'HeavenBridge\verify-v6'
git -C $repo fetch origin +refs/heads/main:refs/remotes/origin/main
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
$sha = (git -C $repo rev-parse refs/remotes/origin/main).Trim()
Write-Output "REMOTE_MAIN_SHA=$sha"
if (Test-Path -LiteralPath $tmp) {
  git -C $repo worktree remove --force $tmp 2>$null
  if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Recurse -Force }
}
git -C $repo worktree add --detach $tmp $sha
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
try {
  $worker = Join-Path $tmp 'heaven-bridge\worker.py'
  $test1 = Join-Path $tmp 'heaven-bridge\test_worker.py'
  $test2 = Join-Path $tmp 'heaven-bridge\tests\test_worker.py'
  $psFiles = @(
    (Join-Path $tmp 'heaven-bridge\bootstrap.ps1'),
    (Join-Path $tmp 'heaven-bridge\manage.ps1'),
    (Join-Path $tmp 'heaven-bridge\uia.ps1'),
    (Join-Path $tmp 'heaven-bridge\install-github-runner.ps1')
  )
  foreach ($p in @($worker,$test1,$test2)+$psFiles) { if (-not (Test-Path -LiteralPath $p)) { throw "missing expected path: $p" } }
  python -m py_compile $worker $test1 $test2
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
  python $test1
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
  python $test2
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
  foreach ($ps in $psFiles) {
    $tokens=$null; $errors=$null
    [void][System.Management.Automation.Language.Parser]::ParseFile($ps,[ref]$tokens,[ref]$errors)
    if ($errors.Count -gt 0) { $errors | Out-String | Write-Error; exit 1 }
  }
  $plugin = Get-Content -Raw -LiteralPath (Join-Path $tmp 'heaven-bridge\plugin\plugin.json') | ConvertFrom-Json
  $codex = Get-Content -Raw -LiteralPath (Join-Path $tmp 'heaven-bridge\plugin\.codex-plugin\plugin.json') | ConvertFrom-Json
  if ($plugin.version -ne $codex.version) { throw 'plugin manifest version mismatch' }
  if ($plugin.version -ne '0.6.0') { throw "expected plugin 0.6.0, found $($plugin.version)" }
  git -C $tmp diff --check
  if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
  Write-Output "PLUGIN_VERSION=$($plugin.version)"
  Write-Output 'V6_EXACT_MAIN_GATE_OK'
} finally {
  git -C $repo worktree remove --force $tmp 2>$null
}
